// Hand-written `@nestjs/websockets` stub: only what the extractor reads.

export interface GatewayMetadata {
  /** Endpoint the gateway serves; every event it names is addressed within it. */
  namespace?: string;
  path?: string;
  cors?: unknown;
}

export declare function WebSocketGateway(metadata?: GatewayMetadata): ClassDecorator;

export declare function SubscribeMessage(message: string): MethodDecorator;

export declare function WebSocketServer(): PropertyDecorator;

export declare function MessageBody(): ParameterDecorator;

export declare function ConnectedSocket(): ParameterDecorator;

export interface OnGatewayConnection<T = unknown> {
  handleConnection(client: T): void;
}

export interface OnGatewayDisconnect<T = unknown> {
  handleDisconnect(client: T): void;
}
